normalBranch.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            var reelSpinData = (logicResponse.reelSpinData[0]);
            this._cyclers.stopCyclers();
            if (!logicResponse.baseGameRecoverySpinData) {
                if (logicResponse.reelSpinData[0].bonusAwarded) {
                    this._commonui.stopAutoPlay();
                    this._commonui.disableStopButton();
                    TweenMax.delayedCall(1.0, function () {
                        _this._cyclers.startPreBonusWin(logicResponse, _this._server.getInitResponse());
                    }, [], this);
                }
                else if (reelSpinData.lilSpininfoData != undefined && reelSpinData.lilSpininfoData.numTotalLilSpinsAwarded > 0) {
                    this._commonui.stopAutoPlay();
                    this._commonui.disableStopButton();
                    TweenMax.delayedCall(1.0, function () {
                        _this._cyclers.startPreLockItFeatureAnim(logicResponse, _this._server.getInitResponse());
                    }, [], this);
                }
                else {
                    this._cyclers.startPaylinesCycler(logicResponse, this._server.getInitResponse());
                }
            }
            else {
                this._cyclers.startPaylinesCycler(logicResponse, this._server.getInitResponse(), true);
            }
        }

cashParser.source:
function (input, object) {
            var node = input.getElementsByTagName("GameWinInfo")[0];
            var bgInfoData = new sgigame.BaseGameInfoData;
            bgInfoData.totalWagerWin = parseInt(this.getAttributeFromNode(node, "totalWagerWin", "number"));
            bgInfoData.baseGameWin = parseInt(this.getAttributeFromNode(node, "bgWinnings", "number"));
            bgInfoData.isMaxWin = (this.getAttributeFromNode(node, "isMaxWin") === "Y");
            bgInfoData.maxWinVal = parseInt(this.getAttributeFromNode(node, "maxWin", "number"));
            var bgInfoNode = input.getElementsByTagName("BGInfo")[0];
            if (bgInfoNode)
                bgInfoData.numTotalFreeSpinsAwarded = parseInt(this.getAttributeFromNode(bgInfoNode, "numTotalFreeSpinsAwarded", "number"));
            object.baseGameInfoData = bgInfoData;
        }

