makeInit.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [new sgigame.PageEncoder(this._server.getInitResponse() ? this._server.getInitResponse().pageData.pageIndex + 1 : 0)];
            if (this._historyModel.getIsHistoryReplay() && !this._server.getInitResponse()) {
                encoders.push(new sgigame.HistoryReplaceEncoder(this._historyModel.getNextState()));
                this._historyModel.restart();
            }
            var initData = new server.GLSRequest(encoders);
            this._server.makeInitRequest(initData);
        }

checkInit.source:
function () {
            _super.prototype.execute.call(this);
            if (this._server.getInitResponse().pageData.pageIndex < this._server.getInitResponse().pageData.pageCount - 1) {
                this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.INIT_STAGE_COMPLETE));
            }
            else {
                this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.INIT_COMPLETE));
            }
            if (this._server.getInitResponse().pageData.pageIndex == 0) {
                this._partnerAdapter.receivedGameLogicResponse(this._server.getInitResquester().getRequestObject());
            }
        }

