function (input, object) {
            var data = new sgigame.PageData();
            var node = input.getElementsByTagName("PageInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.pageCount = parseInt(attributes.getNamedItem("pageCount").value);
            }
            var node = input.getElementsByTagName("Page")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.pageIndex = parseInt(attributes.getNamedItem("pageIndex").value);
            }
            object.pageData = data;
        }
